/* Cockpit UI. Vanilla JS. State: env (scan), sessions, runs (+ live output), route. */
const S = { env: null, meta: null, sessions: [], transcripts: null, changes: [], transcriptCache: {}, runs: new Map(), route: { view: 'overview', id: null, tab: null }, filters: {}, claudeSessions: {}, files: {} };
const $ = (sel, el = document) => el.querySelector(sel);
