const kv = (pairs) => h('div', { class: 'kv' }, pairs.filter((p) => p && p[1] != null && p[1] !== '').map(([k, v, cls]) => [h('div', { class: 'k' }, k), h('div', { class: 'v ' + (cls || '') }, v)]));
const fmtT = (iso) => iso ? new Date(iso).toLocaleTimeString([], { hour12: false }) : '';
const fmtD = (iso) => iso ? new Date(iso).toLocaleString([], { hour12: false }) : '';
const dur = (a, b) => a ? `${Math.max(0, Math.round(((b ? new Date(b) : new Date()) - new Date(a)) / 1000))}s` : '';
const short = (p) => p ? p.replace(S.env?.machine.home || '~', '~') : '';
// Where this machine's Claude/Codex state actually lives (follows CLAUDE_CONFIG_DIR / CODEX_HOME), for display.
const claudeAt = (rel = '') => short((S.env?.claude.home || '~/.claude') + rel), codexAt = (rel = '') => short((S.env?.codex.home || '~/.codex') + rel), claudeJsonAt = () => short(S.env?.claude.jsonPath || '~/.claude.json');
