function go(view, id = null, tab = null) { if (view !== S.route.view) S.focusKey = null; S.route = { view, id, tab }; location.hash = [view, id, tab].filter(Boolean).map(encodeURIComponent).join('/'); render(); }
window.addEventListener('hashchange', () => { const [view, id, tab] = location.hash.slice(1).split('/').map((x) => x && decodeURIComponent(x)); if (view && (view !== S.route.view || id !== S.route.id || tab !== S.route.tab)) { if (view !== S.route.view) S.focusKey = null; S.route = { view, id: id || null, tab: tab || null }; render(); } });
const fileLink = (p, label) => h('span', { class: 'link', title: 'open file in Cockpit', onclick: (e) => { e.stopPropagation(); openFile(p); } }, label ?? short(p));
async function openFile(p) { if (!S.files[p]) { S.files[p] = await api('/file?path=' + encodeURIComponent(p)); } S.route.tab = 'file:' + p; render(); }
