function diffPre(text) { const el = h('pre', { class: 'diff tall' }); el.innerHTML = String(text || '').split('\n').map((l) => `<span class="${l.startsWith('+++') || l.startsWith('---') ? 'm' : l.startsWith('+') ? 'a' : l.startsWith('-') ? 'd' : l.startsWith('@@') ? 'h' : /^(diff|index) /.test(l) ? 'm' : ''}">${esc(l)}</span>`).join('\n'); return el; }

// ---------- data ----------
async function loadAll() { let env, meta, sessions, runs, transcripts; try { [env, meta, sessions, runs, transcripts, S.changes] = await Promise.all([api('/env'), api('/meta'), api('/sessions'), api('/runs'), api('/transcripts'), api('/changes')]); } catch (e) { S.loadError = e.message; render(); return; } if (env.error) { S.loadError = env.error; render(); return; } S.loadError = null; S.env = env; S.meta = meta; S.sessions = sessions; S.transcripts = transcripts; for (const r of runs) if (!S.runs.has(r.id)) S.runs.set(r.id, { ...r, chunks: [] }); render(); }
