    if (ev.type === 'run.start' || ev.type === 'run.exit') { const prev = S.runs.get(ev.run.id); S.runs.set(ev.run.id, { ...ev.run, chunks: ev.run.chunks?.length ? ev.run.chunks : (prev?.chunks || []) }); render(); }
