    if (ev.type === 'transcript.changed') { S.liveTranscripts ||= {}; S.liveTranscripts[ev.path] = Date.now(); if (S.transcripts) { const list = S.transcripts[ev.provider]; const t = list.find((x) => x.path === ev.path); if (t) { t.size = ev.size ?? t.size; t.mtime = ev.mtime || t.mtime; } else if (ev.mtime) { const m = ev.path.match(/rollout-(\S+?)-([0-9a-f-]{36})\.jsonl$/); list.push({ provider: ev.provider, id: m ? m[2] : ev.path.split('/').pop().replace('.jsonl', ''), path: ev.path, size: ev.size || 0, mtime: ev.mtime, projectDir: ev.provider === 'claude' ? ev.path.split('/').slice(-2)[0] : undefined, startedAt: m ? m[1] : null }); } }
      if (S.route.view === 'transcripts') { if (S.route.id === ev.path || (!S.route.id && S.transcriptCache[ev.path])) { delete S.transcriptCache[ev.path]; S._followTail = true; } render(); } else if (S.route.view === 'overview' || S.route.view === 'activity') render(); }
    if (ev.type === 'env.changed') { S.rescanning = ev.changed; render(); }
    if (ev.type === 'env.scanned') { if (ev.changes?.length) S.changes = [...ev.changes.slice().reverse(), ...S.changes]; api('/env').then((e) => { S.env = e; S.rescanning = null; render(); }); }
